export const HEADER =
  '<!-- AUTO-GENERATED by @odh-dashboard/extension-map. Do not edit by hand. -->\n\n> Generated file. Regenerate with `pnpm docs:extension-map`.';

/** Escapes Markdown table pipes and makes line breaks explicit within a cell. */
export const escapeCell = (value: string): string =>
  value.replace(/\|/gu, '\\|').replace(/\r?\n/gu, '<br>');

export const table = (headers: string[], rows: string[][]): string => {
  const header = `| ${headers.map(escapeCell).join(' | ')} |`;
  const separator = `| ${headers.map(() => '---').join(' | ')} |`;
  const body = rows.map(
    (row) => `| ${headers.map((_, index) => escapeCell(row[index] ?? '')).join(' | ')} |`,
  );
  return [header, separator, ...body].join('\n');
};

export const defList = (items: [string, string][]): string =>
  items
    .map(([term, description]) => `- **${escapeCell(term)}**: ${escapeCell(description)}`)
    .join('\n');
